#!/usr/bin/env python3
"""Publish compact, path-free local benchmark evidence and Markdown results."""
import json,pathlib,statistics,datetime,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[2];T=ROOT/'target/goose'
def main():
    reports=[json.loads(p.read_text()) for p in sorted((T/'runs').glob('*/results.json'))]
    assert len(reports)==7
    for report in reports:
        for row in report['rows']:
            assert len(row['ms'])>=7
            if report['mode']!='samplers':
                if row['language']=='rust':assert set(row['hashes'])=={row['output_sha256']}
                else:assert set(row['checksums'])=={int.from_bytes(bytes.fromhex(row['output_sha256'])[:8],'little')}
            elif 'checksums' in row:assert len(set(row['checksums']))==1
    validation=json.loads((T/'validation.json').read_text())
    full=[r for p in sorted(T.glob('full-validation-*.json')) for r in json.loads(p.read_text())]
    assert len(full)==8
    build=json.loads((T/'build.json').read_text())
    compact={'measurement_notes':['All durations are internal native elapsed times; process startup and language bridges are excluded.', 'The host was not CPU-affinity-pinned or otherwise isolated. The 60 MP parallel and IIR diagnostic runs have substantial spread; pooled medians are descriptive, and paired batch ratios are retained.', 'Full grain favors Rust in every measured configuration and paired batch; these results characterize this implementation on macOS arm64.'],'measurement_source_revision':'38722c36f72ae3c6a0113c492b98a4c39032359e','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'platform':'macOS 26.5.2 arm64, Apple M1 Pro, 10 CPU cores, 32 GiB RAM','build':build,'validation':{'differential_cases':len(validation['rows']),'max_bit_differences':max(r['bit_differences'] for r in validation['rows']),'malformed_rejections':len(validation['malformed']),'full_resolution':[{k:r[k] for k in ['fixture','language','budget','output_sha256']} for r in full]},'results':reports}
    (ROOT/'docs/goose-cpu-results.json').write_text(json.dumps(compact,indent=2)+'\n')
    grain=sorted((r for r in reports if r['mode']=='grain'),key=lambda r:(r['width'],r['workers']))
    def spread(v, scale=1.):return f"{v['median_ms']*scale:.2f} ({v['min_ms']*scale:.2f}–{v['max_ms']*scale:.2f})"
    lines=['# Standalone Goose grain results','', 'The faithful Goose port passes bit-exact validation, but offers no full-grain speedup in the measured configurations and uses more resident memory. Completed on macOS arm64. These timings cover the complete native f64 grain call, with every required grain effect enabled. They exclude process startup, decoding, fixture loading, input restoration, pool initialization, checksums and any application/language bridge. Required Goose worker copies and dispatch are included.', '', '| Frozen photo | CPU budget | Rust median s (min–max) | Goose median s (min–max) | Rust / Goose | Paired batch ratios |','| --- | ---: | ---: | ---: | ---: | --- |']
    for r in grain:lines.append(f"| {r['width']}×{r['height']} | {r['workers']} | {spread(r['summary']['rust'],.001)} | {spread(r['summary']['goose'],.001)} | {r['rust_over_goose']:.3f}× | {', '.join(f'{x:.3f}×' for x in r['batch_ratios'])} |")
    lines+=['','A ratio above 1 means Goose was faster. This is one faithful implementation comparison on this machine; it is not a whole-export or general language benchmark.','', 'The host was not CPU-affinity-pinned or otherwise isolated. The 60 MP parallel measurements and IIR diagnostics have substantial spread. Pooled median ratios are descriptive; paired batch ratios show the effect of collecting variants at different times. The data support the qualitative result above, but not a precise universal slowdown percentage or a causal explanation for the variation.', '', '## Correctness','',f"All {len(validation['rows'])} native differential cases have zero bit differences; both native loaders reject all eight malformed-file checks. The sampler corpus contains 146,960 values, including integer/uniform streams, switch boundaries, rejection paths, normal-cache reuse and next RNG draws for five seeds. Full-size outputs are bit-identical across both executables and budgets 1 and 4. No floating tolerance was needed.", '', 'The synthetic suite covers colour, positive interpolation and monochrome, 1/3/4 layers, 1×1, 1×N, N×1 and odd dimensions, zero RMS, zero-density layers, duplicate curve positions and NaN curve entries. FIR/IIR tests include identity, tiny sigma, wide kernels and either side of sigma 3. Rust’s existing sampler, model, Python-derived grain statistics and blur-edge baseline tests all passed (3, 5, 8 and 6 tests respectively).', '', '## Fixtures and active effects','']
    for name in ['nikon24','leica60']:
        m=json.loads((T/'fixtures'/name/'metadata.json').read_text());e=m['effects'];sigmas=[x for row in e['dye_sigmas'] for x in row]
        lines.append(f"- {name}: {m['width']}×{m['height']}, {m['pixel_size_um']:.17g} µm/px, {m['n_layers']} layers; microstructure sigma {e['micro_sigma']:.6g} (>0.05), microstructure blur {e['micro_blur']:.6g} px (>0.4), dye-cloud sigma {min(sigmas):.6g}–{max(sigmas):.6g} px. Pixel blur 0.89 uses FIR; sharpening sigma 3.5, amount 1.5 uses IIR. Dye blur runs for every sampled layer; the finest layers’ rounded FIR radii can be zero.")
    lines+=['', 'Both fixtures use resolved `kodak_gold_200` curves/settings from the same newly built CPU pipeline that emitted pre-grain density, with `kodak_portra_endura` selected during capture. RAWs were decoded with Rawler. The chosen capture recipe was unchanged. Pixel arrays and private paths are excluded from version control; only hashes and compact measurements are published here. Sanitized fixture manifests are retained in `experimental/goose-grain/fixtures/`.', '', '## Measurement policy','', 'Each variant has fourteen measured calls in two native process batches (seven per process), AB then BA, with one warmup per process. Each input is restored through a fresh deep copy immediately before its internal monotonic timer. Outputs are consumed after every call; the final full output is SHA-256 checked after every batch. Full-size equality was established before benchmark runs. Benchmarks ran sequentially, after builds, captures and validation completed.', '', 'Budget 1 executes directly in Goose and uses one Rayon worker in Rust. Budget 4 uses three persistent Goose channel workers plus the coordinator, versus four Rayon workers. The coordinator packs channel inputs and sends copied flat jobs; packing, queue copies, receive and HWC assembly are timed. Goose blur is serial within each channel, while Rust can parallelize interpolation/filter passes. The one-thread Goose path also packs channel inputs so it can use the same planar channel routine; that packing is timed. The additional throughput and memory costs are part of this implementation result. No pointer tokens or shared-memory workaround was used.', '', 'Goose v2026.3 is pinned to commit `8511ae34bdc9aabf77baaab80b4d659ea87835e2`, runtime `4d3da949e563`. Goose -O2 controls inlining; standalone generated C uses Apple clang 21.0.0, `-O3 -ffp-contract=off`. Rust 1.93.1 uses release opt-level 3, thin LTO and one codegen unit. Both use the default arm64 target CPU and strict floating evaluation. Dependency versions match the workspace lock; the separate experiment lock adds SHA-256 support.', '', 'Goose calls the identical pinned `libm` 0.2.16 `lgamma` scalar primitive directly, since its standard math module lacks it. This shared native math routine is timed on both sides. Grain, MT19937, distribution algorithms, blur and worker processing are implemented in Goose; no language bridge or cross-language runtime dispatcher is in either timer. Native support for fixture hashing/loading and RSS runs outside timing. See [provenance and notices](../experimental/goose-grain/NOTICE.md).', '', '## Supporting diagnostics','', '| Operation (one thread) | Rust median ms (min–max) | Goose median ms (min–max) | Rust / Goose |', '| --- | ---: | ---: | ---: |']
    for r in reports:
        if r['mode']=='grain':continue
        label='Sampler corpus (146,960 values)' if r['mode']=='samplers' else f"24 MP single-plane blur, sigma {r['sigma']}"
        lines.append(f"| {label} | {spread(r['summary']['rust'])} | {spread(r['summary']['goose'])} | {r['rust_over_goose']:.3f}× |")
    lines+=['', 'Sampler diagnostics include corpus output allocation/construction and RNG initialization. Blur diagnostics include scratch/output allocations; channel extraction and sigma parsing are outside both timers. These diagnostics do not replace complete grain timings.', '', '## Memory','', '| Frozen photo | Budget | Rust peak / retained MiB | Goose peak / retained MiB |','| --- | ---: | ---: | ---: |']
    for r in grain:
        def mem(lang):
            s=r['summary'][lang];return f"{s['peak_rss_bytes']/2**20:.0f} / {s['retained_rss_bytes']/2**20:.0f}"
        lines.append(f"| {r['fixture']} | {r['workers']} | {mem('rust')} | {mem('goose')} |")
    lines+=['', 'Peak is macOS `time -l` maximum resident set size for the entire process, including fixture loading and validation. Retained is the maximum Mach task resident size sampled immediately after a timed call, with immutable input and completed output still alive. These are resident-memory measurements, not allocation totals or isolated scratch peaks. Goose reserves 2 GiB per data stack: 27 main/global regions (54 GiB virtual) and 11 additional regions per worker. Budget 4 has 60 regions (120 GiB virtual), plus 1 MiB guard per region. These compiler-reported virtual reservations are separate from physical RSS; see `target/goose/goose-build.log`.', '', '## Reproduction and limits','', 'See [the experiment README](../experimental/goose-grain/README.md) for build, capture, validation and batch commands. Compact raw per-call durations, checksums, hashes, IQR, per-batch ratios, compiler settings and memory measurements are in [goose-cpu-results.json](goose-cpu-results.json). Generated private artifacts, toolchains and logs go under ignored `target/goose/` and can be removed after recording the results.', '', 'Measurements used source revision `38722c36f72ae3c6a0113c492b98a4c39032359e` (0.8.0). Publishing onto current main updated only the experiment lock’s five local workspace package versions to 0.9.0; measured numerical sources and registry dependency versions are unchanged. Sanitized fixture manifests preserve the original metadata hashes and numerical inputs’ payload hashes. Private pixel dumps and generated caches are disposable and are not committed.', '', 'This implementation and report cover macOS arm64. Windows/Linux were not measured; current hashing/RSS support is macOS-specific. Pools are persistent and initialized before timing. No application ABI or service-thread integration was added. Unrelated tracked/untracked work was preserved; experiment code is confined to `experimental/goose-grain/`, `scripts/goose/` and these result documents.', '', 'Official compiler evidence: [release v2026.3](https://github.com/aardappel/goose/releases/tag/v2026.3), [pinned language and runtime sources](https://github.com/aardappel/goose/tree/8511ae34bdc9aabf77baaab80b4d659ea87835e2).']
    (ROOT/'docs/goose-cpu-results.md').write_text('\n'.join(lines)+'\n')
    print('Wrote docs/goose-cpu-results.md and .json')
if __name__=='__main__':main()
